using System;
using UnityEngine;

public class KFMonoBehaviourCallbackHooks : MonoBehaviour
{
	private static KFMonoBehaviourCallbackHooks instance;

	private Action m_OnLateUpdateDelegate;

	public static KFMonoBehaviourCallbackHooks Instance
	{
		get
		{
			if (instance == null)
			{
				instance = new GameObject("KFMonoBehaviourCallbacks").AddComponent<KFMonoBehaviourCallbackHooks>();
			}
			return instance;
		}
	}

	public event Action OnLateUpdateDelegate
	{
		add
		{
			m_OnLateUpdateDelegate = (Action)Delegate.Combine(m_OnLateUpdateDelegate, value);
		}
		remove
		{
			m_OnLateUpdateDelegate = (Action)Delegate.Remove(m_OnLateUpdateDelegate, value);
		}
	}

	private void Awake()
	{
		if (instance == null)
		{
			instance = this;
		}
		else if (instance != this)
		{
			UnityEngine.Object.Destroy(base.gameObject);
			return;
		}
		UnityEngine.Object.DontDestroyOnLoad(base.gameObject);
	}

	private void LateUpdate()
	{
		m_OnLateUpdateDelegate?.Invoke();
	}
}
